// Material recipe approved in CREATURE-EMISSION-ADDITIONS-20261101-R1.
export const SCENERY_EMISSION_SPEC=Object.freeze({maxSources:12,maxCachedFrames:48,maxMushrooms:24,maxHaloCaches:24});
export const HEDGEHOG_EMISSION_COLORS=Object.freeze(['#5ee9e9','#47f641','#ece910','#f94e6d','#f94e6d','#ece910','#47f641']);
export function paintCapShapes(c,a){
 for(const s of a.shapes){const p=new Path2D(s.type==='path'?s.d:undefined);if(s.type==='ellipse')p.ellipse(s.cx,s.cy,s.rx,s.ry,0,0,Math.PI*2);else if(s.type!=='path')p.roundRect(s.x,s.y,s.width,s.height,s.radius);c.save();if(s.matrix)c.transform(...s.matrix);c.fillStyle=s.fill;c.fill(p);c.restore();}
}
export function createSceneryEmissionMaterials({makeCanvas,canonicalAtlas,materialRamps}){
 const templates=new Map(),rasters=new WeakMap(),resident=new Map(),mushrooms=new Map();let bytes=0,dead=false;
 const release=v=>{bytes-=v.canvas.width*v.canvas.height*8;v.canvas.width=v.canvas.height=v.raw.width=v.raw.height=1;};
 function template(frame){if(templates.has(frame))return templates.get(frame);const c=makeCanvas(384,320),g=c.getContext('2d');g.drawImage(canonicalAtlas,frame*384,0,384,320,0,0,384,320);const d=g.getImageData(0,0,384,320).data,alpha=new Uint8Array(384*320);let left=384,top=320,right=0,bottom=0,count=0;for(let j=0;j<alpha.length;j++){const i=j*4,r=d[i],a=d[i+1],b=d[i+2];if(a>90&&b>100&&a>r*1.28&&b>r*1.28&&d[i+3]){alpha[j]=d[i+3];const x=j%384,y=Math.floor(j/384);left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);count++;}}c.width=1;const value={alpha,left:Math.max(0,left-8),top:Math.max(0,top-8),right:Math.min(383,right+8),bottom:Math.min(319,bottom+8),count};templates.set(frame,value);return value;}
 function glow(mask,color,blur,gain,second){const c=makeCanvas(mask.width,mask.height),g=c.getContext('2d');g.shadowColor=color;g.shadowBlur=blur;g.globalAlpha=gain;g.drawImage(mask,0,0);g.shadowBlur=0;g.globalAlpha=second;g.drawImage(mask,0,0);return c;}
 function hedgehog(atlas,frame,biome){if(dead||!canonicalAtlas)return null;frame=Math.max(0,Math.min(15,frame|0));let cache=rasters.get(atlas);if(!cache){cache=new Map();rasters.set(atlas,cache);}if(cache.has(frame)){const v=cache.get(frame);resident.delete(v);resident.set(v,{cache,frame});return v;}const t=template(frame),width=t.right-t.left+1,height=t.bottom-t.top+1,mask=makeCanvas(width,height),g=mask.getContext('2d');g.drawImage(atlas,frame*384+t.left,t.top,width,height,0,0,width,height);const im=g.getImageData(0,0,width,height);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=(y*width+x)*4;im.data[i+3]=Math.min(im.data[i+3],t.alpha[(y+t.top)*384+x+t.left]);}g.putImageData(im,0,0);const color=HEDGEHOG_EMISSION_COLORS[biome],v={canvas:glow(mask,color,6,.84,.46),raw:mask,...t,width,height,color};while(resident.size>=SCENERY_EMISSION_SPEC.maxCachedFrames){const old=resident.keys().next().value,ref=resident.get(old);ref.cache.delete(ref.frame);resident.delete(old);release(old);}resident.set(v,{cache,frame});cache.set(frame,v);bytes+=width*height*8;return v;}
 function mushroom(a,type,options){if(dead)return null;const variant=options.variant||0,ramps=materialRamps[options.biome||0].gem;
  // Approved healing/explosive caps and naturally green decorative mushrooms only.
  if(type==='cave-mushroom'&&variant!==0&&variant!==2)return null;
  if(type==='mushroom'){const color=parseInt(ramps[0].slice(1),16),r=color>>16,g=color>>8&255,b=color&255;if(!(g>r*1.15&&g>b*1.15))return null;}
  const key=a.visualKey;if(mushrooms.has(key)){const v=mushrooms.get(key);mushrooms.delete(key);mushrooms.set(key,v);return v;}const colors=type==='cave-mushroom'?(variant===0?['#a2e66f','#5dae27','#288a3f']:['#ffd95a','#f06c1a','#ce2029']):ramps,color=type==='cave-mushroom'&&variant===2?'#ff9438':'#64ff58',selected=a.shapes.filter(s=>colors.includes(s.fill)),mask=makeCanvas(216,236),g=mask.getContext('2d');g.scale(2,2);g.translate(4,4);paintCapShapes(g,{shapes:selected});const v={canvas:glow(mask,color,7,.72,.30),raw:mask,color,selectedFaces:selected.length,totalFaces:a.shapes.length};while(mushrooms.size>=SCENERY_EMISSION_SPEC.maxMushrooms){const first=mushrooms.keys().next().value;release(mushrooms.get(first));mushrooms.delete(first);}mushrooms.set(key,v);bytes+=216*236*8;return v;
 }
 return {hedgehog,mushroom,template,status:()=>({templates:templates.size,mushroomVariants:mushrooms.size,cachedFrames:resident.size,cachedRasterBytes:bytes,templateBytes:templates.size*384*320}),dispose(){if(dead)return;dead=true;for(const v of resident.keys())release(v);for(const v of mushrooms.values())release(v);resident.clear();mushrooms.clear();templates.clear();}};
}
